from playwright.sync_api import sync_playwright
from pathlib import Path
from PIL import Image
import json, os

out=Path(__file__).resolve().parents[1]/'artifacts'/'community-v5';out.mkdir(parents=True,exist_ok=True)
report={'checks':[],'errors':[],'failed_requests':[]}
def check(name,value,detail=None):
    report['checks'].append({'name':name,'passed':bool(value),'detail':detail})
    assert value,(name,detail)
with sync_playwright() as p:
    browser=p.chromium.launch(headless=True,args=['--enable-unsafe-swiftshader'])
    page=browser.new_page(viewport={'width':1440,'height':1100},device_scale_factor=1)
    page.on('pageerror',lambda error:report['errors'].append(str(error)))
    page.on('console',lambda message:report['errors'].append(message.text) if message.type=='error' else None)
    page.on('requestfailed',lambda request:report['failed_requests'].append(request.url))
    page.goto(os.environ.get('WEB_PREVIEW_URL','http://127.0.0.1:4174/?seed=42&players=20&accounts=100&debug=1'),wait_until='networkidle')
    page.wait_for_function('window.__TYPHI__?.ready || document.querySelector(".retry-button")',timeout=90000)
    check('twenty racers and waiting customers initialize',page.evaluate('!!window.__TYPHI__?.ready'),report['errors'])
    page.evaluate("window.__TYPHI__.pause(true);window.__TYPHI__.mode('overview')")
    page.wait_for_timeout(1000)
    race=page.evaluate('window.__TYPHI__.snapshot()');crowd=page.evaluate('window.__TYPHI__.crowd()')
    check('20 independent racers share a three-lap race with a seeded finish',len(race['players'])==20 and len(set(player['seat'] for player in race['players']))==20 and race['race']['lapTarget']==3 and race['race']['totalSteps']==288)
    check('80 customers keep wallets without map actors',len(page.evaluate('window.__TYPHI__.community().accounts'))==100 and page.evaluate('window.__TYPHI__.matchmaking().waitingCount')==80 and page.evaluate('window.__TYPHI__.renderStats().activeActors')==20)
    check('crowd rendering groups the start without dropping logical racers',crowd['logicalPlayers']==20 and crowd['visiblePlayers']<=10 and crowd['finishVisible'],crowd)
    check('expanded scene has no invalid geometry',page.evaluate('window.__TYPHI__.geometryAudit()')==[])
    check('improved front artwork is actually loaded',page.evaluate("performance.getEntriesByType('resource').some(r=>r.name.includes('upgrades/ch07-front-idle.png'))"))
    report['initial_render_stats']=page.evaluate('window.__TYPHI__.renderStats()')
    page.screenshot(path=str(out/'01-twenty-start.png'),full_page=True)
    with page.expect_download() as download_info:
        page.evaluate('window.__TYPHI__.screenshot()')
    download_info.value.save_as(str(out/'map-export-1080x1920.png'))
    with Image.open(out/'map-export-1080x1920.png') as exported:
        check('map export remains a nonblank 1080 by 1920 image',exported.size==(1080,1920) and any(hi>lo for lo,hi in exported.convert('RGB').getextrema()))

    page.evaluate('window.__TYPHI__.pause(false);window.__TYPHI__.startShop()')
    page.wait_for_function("window.__TYPHI__.community().shop?.phase==='ordering'")
    shop=page.evaluate('window.__TYPHI__.community().shop');host=shop['hostId']
    check('active racers cannot occupy customer order slots',page.evaluate('(host)=>window.__TYPHI__.comment("P020",`MUA ${host}`,"racer-order")',host) is False)
    check('waiting customers can order once without paying',page.evaluate('window.__TYPHI__.ordersAll(8)')==8 and page.evaluate('window.__TYPHI__.community().accounts.find(a=>a.id==="P021").money')==1000)
    check('a customer cannot place a second order',page.evaluate('(host)=>window.__TYPHI__.comment("P021",`MUA ${host}`,"second-order")',host) is False)
    page.evaluate('window.__TYPHI__.advance(12.1)')
    check('returns open only after ordering closes',page.evaluate('window.__TYPHI__.community().shop.phase')=='returns' and page.evaluate('window.__TYPHI__.cancelOrders(6)')==6)
    page.evaluate('window.__TYPHI__.advance(12)')
    shop=page.evaluate('window.__TYPHI__.community().shop')
    check('eight orders and six returns settle host once at 950',shop['phase']=='settled' and shop['result']['net']==-50 and shop['result']['after']==950 and page.evaluate('window.__TYPHI__.community().accounts.find(a=>a.id==="P021").money')==1000)
    page.evaluate('window.__TYPHI__.pause(true)');page.wait_for_timeout(200)
    check('compact shop result is visible',page.locator('[data-testid=shop-panel]').is_visible())
    page.screenshot(path=str(out/'01b-customer-shop.png'),full_page=True)
    page.evaluate('window.__TYPHI__.pause(false);window.__TYPHI__.advance(4.2)')

    page.evaluate("window.__TYPHI__.pause(false);window.__TYPHI__.startInvestment({seed:5,flavor:'startup'})")
    page.wait_for_function("window.__TYPHI__.community().investment?.phase==='joining'")
    page.locator('[data-community=join-all]').click()
    joining=page.evaluate('window.__TYPHI__.community()')
    check('100 participants including the owner commit to one escrow',joining['investment']['participants']==100 and joining['totals']['escrow']==10000 and joining['totals']['conserved'])
    before=next(a['money'] for a in joining['accounts'] if a['id']=='P002')
    check('duplicate join cannot charge twice',page.evaluate("window.__TYPHI__.comment('P002','GÓP','duplicate-join')") is False and page.evaluate("window.__TYPHI__.community().accounts.find(a=>a.id==='P002').money")==before)
    page.evaluate("window.__TYPHI__.comment('P002','KHÔNG THAM GIA','opt-out')")
    refunded=page.evaluate("window.__TYPHI__.community().accounts.find(a=>a.id==='P002').money")
    page.evaluate("window.__TYPHI__.comment('P002','THAM GIA','rejoin')")
    check('opt out refunds the stake once before rejoining',refunded==before+100 and page.evaluate('window.__TYPHI__.community().investment.participants')==100)
    page.evaluate('window.__TYPHI__.advance(10.1)')
    check('chart starts only after the contribution window locks',page.evaluate('window.__TYPHI__.community().investment.phase')=='chart' and page.locator('.investment-chart').is_visible())
    page.evaluate('window.__TYPHI__.advance(4)');page.evaluate('window.__TYPHI__.pause(true)')
    chart=page.evaluate('window.__TYPHI__.community().investment.chart')
    check('simulated chart reveals only its elapsed portion',0<chart['progress']<1 and len(chart['points'])>1)
    page.screenshot(path=str(out/'02-investment-chart.png'),full_page=True)
    page.evaluate('window.__TYPHI__.pause(false);window.__TYPHI__.advance(4)')
    settled=page.evaluate('window.__TYPHI__.community()')
    check('all 100 receive one up-chart settlement including host',settled['investment']['result']['direction']=='up' and len(settled['investment']['result']['results'])==100 and settled['totals']['escrow']==0 and settled['totals']['conserved'])
    check('each participant receives principal plus the advertised gain',all(row['returned']>row['stake'] and row['after']>=0 for row in settled['investment']['result']['results']))
    page.evaluate('window.__TYPHI__.pause(true)');page.screenshot(path=str(out/'03-investment-result.png'),full_page=True)
    page.evaluate("window.__TYPHI__.pause(false);window.__TYPHI__.advance(4.2);window.__TYPHI__.startInvestment({seed:0,flavor:'startup'});window.__TYPHI__.joinAll();window.__TYPHI__.advance(18.1)")
    losing=page.evaluate('window.__TYPHI__.community()')
    check('down chart debits the owner and all 99 contributors alike',losing['investment']['result']['direction']=='down' and all(row['net']<0 for row in losing['investment']['result']['results']) and losing['totals']['conserved'])
    page.evaluate('window.__TYPHI__.pause(true)');page.screenshot(path=str(out/'03b-startup-loss.png'),full_page=True)
    page.evaluate('window.__TYPHI__.pause(false);window.__TYPHI__.advance(4.2);window.__TYPHI__.startEnvelope(42)')
    page.locator('[data-community=hearts-all]').click()
    envelope=page.evaluate('window.__TYPHI__.community().redEnvelope')
    check('1000 hearts trigger one ranked payout to racers and customers',envelope['hearts']==1000 and envelope['phase']=='settled' and len(envelope['result']['payouts'])==100 and sum(row['amount'] for row in envelope['result']['payouts'])==envelope['result']['pot'])
    page.evaluate('window.__TYPHI__.pause(true)');page.screenshot(path=str(out/'04-ranked-envelope.png'),full_page=True)
    page.evaluate("window.__TYPHI__.pause(false);window.__TYPHI__.advance(5.2);window.__TYPHI__.rose('P100','rose-test')")
    check('a finalized rose is deduplicated',page.evaluate("window.__TYPHI__.rose('P100','rose-test')") is False)
    page.evaluate('window.__TYPHI__.startEnvelope(7);window.__TYPHI__.startShop();window.__TYPHI__.ordersAll(8);window.__TYPHI__.heartsAll()')
    queued=page.evaluate('window.__TYPHI__.community()')
    check('full envelope queues behind an active customer shop',queued['shop']['phase']=='ordering' and queued['redEnvelope']['phase']=='settled' and queued['modal']=='shop' and page.evaluate('window.__TYPHI__.snapshot().globalHold'))
    page.evaluate('window.__TYPHI__.advance(12.1);window.__TYPHI__.cancelOrders(6);window.__TYPHI__.advance(12)')
    shared=page.evaluate('window.__TYPHI__.community()')
    own=shared['shop']['result']
    check('shop profit excludes concurrent envelope income',own['net']==-50 and own['before']+own['net']==own['after'] and own['openingBalance']+own['net']+own['concurrentDelta']==own['after'] and own['concurrentDelta']>0 and shared['totals']['conserved'])
    page.evaluate('window.__TYPHI__.advance(4.2)')
    check('queued envelope takes over without releasing the shared hold',page.evaluate('window.__TYPHI__.community().modal')=='envelope' and page.evaluate('window.__TYPHI__.snapshot().globalHold'))
    page.evaluate('window.__TYPHI__.advance(5.2)')
    page.evaluate('window.__TYPHI__.advance(12)')
    running=page.evaluate('window.__TYPHI__.snapshot()')
    check('many racers actually move concurrently',sum(player['raceSteps']>0 for player in running['players'])>5)
    page.evaluate('window.__TYPHI__.pause(true)');page.screenshot(path=str(out/'05-concurrent-racers.png'),full_page=True)
    page.set_viewport_size({'width':390,'height':844});page.wait_for_timeout(300)
    rect=page.locator('#game').bounding_box()
    check('20-player mobile viewport keeps portrait aspect without overflow',abs(rect['width']/rect['height']-9/16)<.005 and page.evaluate('document.documentElement.scrollWidth<=innerWidth'))
    page.screenshot(path=str(out/'06-mobile-community.png'),full_page=True)
    page.evaluate('window.__TYPHI__.pause(false);window.__TYPHI__.advance(2800)')
    final=page.evaluate('window.__TYPHI__.snapshot()')
    check('match ends at exactly three actual three-lap finishers',final['race']['over'] and len(final['race']['finishers'])==3 and all(row['raceSteps']==288 and row['laps']==3 for row in final['players'] if row['finished']))
    page.evaluate('window.__TYPHI__.pause(true)');page.wait_for_timeout(200)
    check('top three podium is displayed',page.locator('.race-podium').is_visible() and page.locator('.podium-place').count()==3)
    page.screenshot(path=str(out/'07-top-three.png'),full_page=True)
    old_seed=final['seed'];old_ids=[row['seat'] for row in final['players']]
    page.evaluate('window.__TYPHI__.pause(false)')
    page.wait_for_function('window.__TYPHI__.matchmaking().phase==="reserving"',timeout=30000)
    lobby=page.evaluate('window.__TYPHI__.matchmaking()')
    check('podium opens a timed reservation lobby',lobby['timeleft']<=15 and lobby['settings']['threshold']==30 and lobby['settings']['reserved']==12)
    page.evaluate('(ids)=>ids.slice(0,13).forEach((id,i)=>window.__TYPHI__.like(id,30,`reserve-browser-${i}`))',old_ids)
    reserved=page.evaluate('window.__TYPHI__.matchmaking()')
    check('only first twelve qualified previous racers keep seats',len(reserved['reservations'])==12 and len(reserved['qualified'])==13)
    page.wait_for_timeout(200);page.screenshot(path=str(out/'08-reservation-lobby.png'),full_page=True)
    try:
        page.wait_for_function('(old)=>window.__TYPHI__.snapshot().seed!==old && !window.__TYPHI__.snapshot().loading',arg=old_seed,timeout=60000)
    except Exception:
        print(json.dumps({'snapshot':page.evaluate('window.__TYPHI__.snapshot()'),'community':page.evaluate('window.__TYPHI__.community()'),'errors':report['errors']},ensure_ascii=True))
        raise
    renewed=page.evaluate('window.__TYPHI__.snapshot()')
    expected=set(old_ids[:12]+[f'P{i:03d}' for i in range(21,29)])
    check('matchmaking starts 12 retained racers plus 8 oldest customers',len(renewed['players'])==20 and {row['seat'] for row in renewed['players']}==expected and not renewed['race']['over'] and len(renewed['race']['finishers'])==0)
    check('old racers return behind existing waiting customers',page.evaluate('window.__TYPHI__.matchmaking().waitingIds')==[f'P{i:03d}' for i in range(29,101)]+old_ids[12:])
    check('new match resets every wallet and retains unused customer rose',all(row['money']==1000 for row in page.evaluate('window.__TYPHI__.community().accounts')) and page.evaluate('window.__TYPHI__.community().accounts.find(a=>a.id==="P100").roseCredits')==1)
    report['renewed_render_stats']=page.evaluate('window.__TYPHI__.renderStats()')
    check('MC handoff emits script text without creating a voice service',len(page.evaluate('window.__TYPHI__.mcCues()'))>0)
    check('no browser errors or failed requests',not report['errors'] and not report['failed_requests'],{'errors':report['errors'],'failed_requests':report['failed_requests']})
    browser.close()
report['status']='PASS';(out/'report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps({'status':'PASS','checks':len(report['checks'])}))
